import * as T from './vendor/three.module.js';
import {FURNITURE} from './furniture-catalogue.js';
export function makeFurniture(id){
 const item=FURNITURE[id];if(!item)throw Error('Unknown furniture');const group=new T.Group(),materials=new Map();group.userData.furnitureItem=id;
 const mat=c=>{if(!materials.has(c))materials.set(c,new T.MeshStandardMaterial({color:c,roughness:.78}));return materials.get(c)};
 function mesh(geo,c,x=0,y=0,z=0){const o=new T.Mesh(geo,mat(c));o.position.set(x,y,z);o.castShadow=o.receiveShadow=true;group.add(o);return o;}
 const box=(w,h,d,c,x=0,y=0,z=0)=>mesh(new T.BoxGeometry(w,h,d),c,x,y,z),cyl=(r,h,c,x=0,y=0,z=0)=>mesh(new T.CylinderGeometry(r,r,h,20),c,x,y,z),wood='#815b3e',oak='#b9946a',brass='#b89857';
 function legs(w,d,h){for(const x of [-w/2,w/2])for(const z of [-d/2,d/2])box(.045,h,.045,wood,x,h/2,z);}
 if(id==='round-table'){cyl(.275,.045,wood,0,.53);cyl(.033,.5,brass,0,.25);cyl(.19,.035,brass,0,.02);cyl(.26,.008,oak,0,.557);}
 if(id==='coffee-table'){const top=box(1.05,.055,.55,oak,0,.39);legs(.86,.38,.38);box(.83,.025,.4,wood,0,.14);box(.23,.025,.16,'#536e65',-.15,.435);box(.19,.015,.14,'#e0c89c',-.14,.455);cyl(.055,.035,'#ddd0b8',.25,.445);}
 if(id==='bookcase'){for(const x of [-.405,.405])box(.04,1.55,.35,wood,x,.775);for(const y of [.12,.59,1.06,1.52])box(.85,.035,.35,oak,0,y);box(.81,1.4,.015,'#b69c75',0,.81,-.165);for(let shelf=0;shelf<3;shelf++)for(let i=0;i<5;i++)box(.055,.22+(i%3)*.03,.21,['#365b58','#a16c52','#d2ba88'][i%3],-.32+i*.065,.24+shelf*.47+(i%3)*.015,-.02);cyl(.07,.14,'#e6d7b8',.24,.69);cyl(.05,.19,'#4c7770',.2,1.17);}
 if(id==='cabinet'){legs(.72,.25,.16);box(.9,.55,.4,wood,0,.44);box(.91,.04,.42,oak,0,.735);for(const x of [-.215,.215]){box(.405,.47,.025,'#c3a27b',x,.44,.213);for(let j=0;j<10;j++)box(.008,.44,.012,oak,x-.18+j*.04,.44,.231);for(let j=0;j<12;j++)box(.38,.007,.012,'#a7835a',x,.23+j*.038,.239);cyl(.025,.018,brass,x+(x<0?.14:-.14),.47,.26).rotation.x=Math.PI/2;}}
 if(id==='floor-lamp'){cyl(.18,.035,brass,0,.02);cyl(.016,1.3,brass,0,.67);const shade=mesh(new T.CylinderGeometry(.14,.19,.31,24,1,true),'#ead8b2',0,1.48);shade.material.side=T.DoubleSide;shade.material.emissive.set('#8f6836');shade.material.emissiveIntensity=.24;cyl(.025,.06,'#fff2c9',0,1.43);}
 if(id==='plant'){mesh(new T.CylinderGeometry(.18,.12,.3,20),'#aa7053',0,.16);cyl(.17,.018,'#40372a',0,.315);for(let i=0;i<9;i++){const angle=i*2.4,h=.65+(i%3)*.19,stem=cyl(.009,h-.3,'#57633b',Math.cos(angle)*.05,.3+(h-.3)/2,Math.sin(angle)*.05);stem.rotation.z=Math.sin(angle)*.13;const leaf=mesh(new T.SphereGeometry(1,10,7),i%2?'#486248':'#718253',Math.cos(angle)*.13,h,Math.sin(angle)*.13);leaf.scale.set(.085,.24,.025);leaf.rotation.set(.5*Math.sin(angle),angle,.55*Math.cos(angle));}}
 if(item.flat){box(item.w,.012,item.d,id==='rug'?'#d1b98c':'#355773',0,.006);const long=id==='rug';for(let j=0;j<11;j++){const x=(j-5)*item.w/12;box(item.w/24,.003,item.d*.87,j%3===0?'#9b644e':j%3===1?'#e3d5b4':'#536b5b',x,.014);}for(const z of [-item.d/2,item.d/2])for(let j=0;j<18;j++)box(.012,.003,.045,'#daceb1',(j-8.5)*item.w/18,.005,z);}
 return group;
}
export function disposeFurniture(group,{textures=false}={}){const geometries=new Set(),materials=new Set();group.traverse(o=>{if(o.isMesh){geometries.add(o.geometry);for(const m of Array.isArray(o.material)?o.material:[o.material])materials.add(m)}});for(const g of geometries)g.dispose();if(textures){const maps=new Set();for(const m of materials)for(const key of ['map','normalMap','roughnessMap'])if(m[key])maps.add(m[key]);for(const map of maps)map.dispose();}for(const m of materials)m.dispose();}
export function attachDecor(interior,state){const layer=new T.Group();layer.name='owned-furniture';interior.room.add(layer);const original=interior.getColliders;interior.getColliders=()=>[...original(),...state.decor.items.filter(i=>i.placed&&!FURNITURE[i.item].flat).map(i=>({x:i.x,z:i.z,w:i.turn%2?FURNITURE[i.item].d:FURNITURE[i.item].w,d:i.turn%2?FURNITURE[i.item].w:FURNITURE[i.item].d}))];function refresh(){for(const child of [...layer.children]){disposeFurniture(child);layer.remove(child)}for(const instance of state.decor.items.filter(i=>i.placed)){const m=makeFurniture(instance.item);m.position.set(instance.x,FURNITURE[instance.item].flat?.195:.16,instance.z);m.rotation.y=instance.turn*Math.PI/2;m.userData.instanceId=instance.id;layer.add(m);}}refresh();return {refresh,layer};}
